content:
/* ==========================================================================
   日本の地理クイズ - 和風モダン スタイルシート
   ========================================================================== */

:root {
  /* 和風伝統色パレット */
  --color-ai: #1d3557;          /* 藍色 (Deep Indigo) */
  --color-ai-dark: #102136;     /* 濃藍 */
  --color-asagi: #457b9d;       /* 浅葱色 (Muted Cyan Blue) */
  --color-moegi: #2b7a4b;       /* 萌黄色・常磐色 (Rich Green) */
  --color-moegi-light: #e8f5e9; /* 薄萌黄 (Soft Green) */
  --color-beni: #c53030;        /* 紅緋色 (Vermilion Crimson) */
  --color-beni-light: #ffebee;  /* 薄紅 (Soft Crimson) */
  --color-yamabuki: #d97706;    /* 山吹色 (Gold Amber) */
  --color-washi: #fcfbf7;       /* 和紙色 (Warm Paper White) */
  --color-kinari: #f3efe6;      /* 生成り (Warm Off-white) */
  --color-sumi: #242424;        /* 墨色 (Charcoal Text) */
  --color-hai: #5a626a;         /* 灰色 (Muted Grey) */
  --color-border: #e2dcd2;      /* 枠線色 */

  /* エレベーション・シャドウ */
  --shadow-sm: 0 2px 4px rgba(29, 53, 87, 0.06);
  --shadow-md: 0 6px 16px rgba(29, 53, 87, 0.08), 0 1px 3px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 12px 28px rgba(29, 53, 87, 0.12), 0 3px 8px rgba(0, 0, 0, 0.06);

  /* 角丸 */
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-full: 9999px;

  /* トランジション */
  --transition-fast: 0.18s ease;
  --transition-normal: 0.28s ease;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Hiragino Kaku Gothic ProN", "Hiragino Sans", "BIZ UDPGothic", "Yu Gothic Medium", "Meiryo", sans-serif;
  background-color: var(--color-kinari);
  background-image: 
    radial-gradient(#e6ded2 1px, transparent 1px),
    linear-gradient(to bottom, #f7f3ec 0%, #ebe4d8 100%);
  background-size: 24px 24px, 100% 100%;
  color: var(--color-sumi);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 16px;
  -webkit-font-smoothing: antialiased;
}

/* メインコンテナ */
.quiz-app {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ヘッダー */
.quiz-header {
  text-align: center;
  padding: 8px 12px;
}

.quiz-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--color-ai);
  letter-spacing: 0.06em;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-bottom: 6px;
}

.quiz-subtitle {
  font-size: 0.95rem;
  color: var(--color-hai);
  font-weight: 500;
  letter-spacing: 0.02em;
}

/* プログレスバー */
.progress-wrapper {
  background: var(--color-washi);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 12px 18px;
  box-shadow: var(--shadow-sm);
}

.progress-info {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--color-ai);
  margin-bottom: 8px;
}

.progress-bar-bg {
  width: 100%;
  height: 8px;
  background-color: #e5ded2;
  border-radius: var(--radius-full);
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--color-asagi), var(--color-ai));
  border-radius: var(--radius-full);
  transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* クイズカード */
.quiz-card {
  background: var(--color-washi);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  box-shadow: var(--shadow-md);
  position: relative;
  overflow: hidden;
}

.quiz-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--color-asagi), var(--color-ai));
}

.question-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.badge-prefecture {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background-color: #eaf1f8;
  color: var(--color-ai);
  font-size: 0.8rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  border: 1px solid #d0e0ee;
  letter-spacing: 0.02em;
}

.question-text {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-sumi);
  line-height: 1.5;
  margin-bottom: 22px;
}

/* 4択選択肢グリッド */
.options-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  margin-bottom: 20px;
}

@media (min-width: 540px) {
  .options-grid {
    grid-template-columns: 1fr 1fr;
  }
}

.option-btn {
  display: flex;
  align-items: center;
  width: 100%;
  padding: 14px 16px;
  border-radius: var(--radius-md);
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: all var(--transition-fast);
  border: 2px solid transparent;
  outline: none;
  min-height: 58px;
  position: relative;
}

.option-btn:disabled {
  cursor: default;
}

.option-label {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  font-size: 0.88rem;
  font-weight: 700;
  margin-right: 12px;
  flex-shrink: 0;
  transition: all var(--transition-fast);
}

.option-text {
  flex-grow: 1;
  line-height: 1.35;
}

/* 選択肢 通常時 */
.option-btn-default {
  background-color: #ffffff;
  border-color: var(--color-border);
  color: var(--color-sumi);
  box-shadow: var(--shadow-sm);
}

.option-btn-default .option-label {
  background-color: #ede7dc;
  color: var(--color-ai);
}

.option-btn-default:hover:not(:disabled) {
  border-color: var(--color-asagi);
  background-color: #f7fafd;
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.option-btn-default:active:not(:disabled) {
  transform: translateY(0);
}

/* 選択肢 正解時 */
.option-btn-correct {
  background-color: var(--color-moegi-light);
  border-color: var(--color-moegi);
  color: #1b4d2e;
  box-shadow: 0 0 0 1px var(--color-moegi);
}

.option-btn-correct .option-label {
  background-color: var(--color-moegi);
  color: #ffffff;
}

/* 選択肢 不正解時 */
.option-btn-incorrect {
  background-color: var(--color-beni-light);
  border-color: var(--color-beni);
  color: #7b1d1d;
  box-shadow: 0 0 0 1px var(--color-beni);
  opacity: 0.9;
}

.option-btn-incorrect .option-label {
  background-color: var(--color-beni);
  color: #ffffff;
}

/* 解説カード */
.explanation-card {
  background-color: #f7f9fc;
  border-left: 4px solid var(--color-ai);
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  padding: 16px 18px;
  margin-top: 16px;
  box-shadow: var(--shadow-sm);
  animation: fadeIn 0.3s ease-out;
}

.explanation-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.explanation-title {
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--color-ai);
}

.explanation-body {
  font-size: 0.92rem;
  color: #374151;
  line-height: 1.6;
}

/* 次へ進むアクションエリア */
.action-wrapper {
  margin-top: 24px;
  display: flex;
  justify-content: flex-end;
}

.next-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background-color: var(--color-ai);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-md);
  padding: 12px 28px;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  transition: all var(--transition-fast);
  box-shadow: 0 4px 10px rgba(29, 53, 87, 0.25);
  min-height: 48px;
}

.next-btn:hover {
  background-color: var(--color-ai-dark);
  transform: translateY(-2px);
  box-shadow: 0 6px 14px rgba(29, 53, 87, 0.35);
}

.next-btn:active {
  transform: translateY(0);
}

/* 結果発表カード */
.result-card {
  background: var(--color-washi);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow-lg);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.result-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 6px;
  background: linear-gradient(90deg, #d97706, #c53030, #1d3557);
}

.result-badge {
  display: inline-block;
  background-color: #fef3c7;
  color: var(--color-yamabuki);
  border: 1px solid #fde68a;
  font-size: 0.85rem;
  font-weight: 700;
  padding: 4px 16px;
  border-radius: var(--radius-full);
  margin-bottom: 12px;
  letter-spacing: 0.04em;
}

.result-score-box {
  display: flex;
  align-items: baseline;
  justify-content: center;
  margin: 10px 0 14px 0;
}

.result-score-num {
  font-size: 4rem;
  font-weight: 800;
  color: var(--color-ai);
  line-height: 1;
}

.result-score-denom {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-hai);
  margin-left: 6px;
}

.result-comment {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-sumi);
  margin-bottom: 28px;
  line-height: 1.5;
}

/* 全問振り返りリスト */
.result-summary-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  text-align: left;
  margin-bottom: 32px;
}

.summary-item {
  padding: 14px 16px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background-color: #ffffff;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.summary-item-correct {
  border-left: 5px solid var(--color-moegi);
  background-color: #fbfdfb;
}

.summary-item-incorrect {
  border-left: 5px solid var(--color-beni);
  background-color: #fffdfd;
}

.summary-q-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--color-sumi);
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.summary-detail {
  font-size: 0.85rem;
  color: var(--color-hai);
  line-height: 1.45;
}

/* 再挑戦ボタン */
.restart-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: linear-gradient(135deg, var(--color-ai), #274b78);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-md);
  padding: 14px 36px;
  font-size: 1.05rem;
  font-weight: 700;
  cursor: pointer;
  transition: all var(--transition-fast);
  box-shadow: 0 4px 12px rgba(29, 53, 87, 0.25);
  min-height: 50px;
}

.restart-btn:hover {
  background: linear-gradient(135deg, var(--color-ai-dark), var(--color-ai));
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(29, 53, 87, 0.35);
}

.restart-btn:active {
  transform: translateY(0);
}

/* アニメーションキーフレーム */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* レスポンシブ微調整 */
@media (max-width: 480px) {
  body {
    padding: 16px 12px;
  }

  .quiz-title {
    font-size: 1.45rem;
  }

  .quiz-card {
    padding: 20px 16px;
  }

  .question-text {
    font-size: 1.1rem;
    margin-bottom: 16px;
  }

  .result-score-num {
    font-size: 3.25rem;
  }

  .result-card {
    padding: 28px 18px;
  }
}

export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  correctIndex: number;
  explanation: string;
  prefecture: string;
}

export interface UserAnswer {
  questionId: number;
  selectedIndex: number;
  isCorrect: boolean;
}

import { QuizQuestion } from './types';

export const quizQuestions: QuizQuestion[] = [
  {
    id: 1,
    question: '日本で最も面積が広い「都道府県」は北海道ですが、2番目に面積が広い都道府県はどこでしょう？',
    options: ['岩手県', '福島県', '長野県', '新潟県'],
    correctIndex: 0,
    explanation: '第1位は北海道（約83,424km²）、第2位は岩手県（約15,275km²）です。第3位は福島県、第4位は長野県と続きます。岩手県は四国4県の面積の合計（約18,800km²）にも迫る広さを誇ります。',
    prefecture: '岩手県'
  },
  {
    id: 2,
    question: '日本一の大きさを誇る湖「琵琶湖」は、滋賀県の総面積の約何分の一を占めているでしょう？',
    options: ['約3分の1', '約6分の1', '約2分の1', '約10分の1'],
    correctIndex: 1,
    explanation: '琵琶湖は県面積の大半を占めていると思われがちですが、実際には滋賀県の面積（約4,017km²）の約6分の1（湖面積は約670km²、約16.7%）です。残りの約6分の5は豊かな森林や平野が占めています。',
    prefecture: '滋賀県'
  },
  {
    id: 3,
    question: '日本で「一番長い川」は信濃川（千曲川）ですが、その全長は約何kmでしょう？',
    options: ['約185km', '約256km', '約367km', '約512km'],
    correctIndex: 2,
    explanation: '信濃川は全長約367kmで日本最長です。長野県内では「千曲川（ちくまがわ）」と呼ばれ、新潟県に入ると「信濃川」と名を変えて日本海へ注ぎます。なお、流域面積が日本一の川は利根川です。',
    prefecture: '新潟県・長野県'
  },
  {
    id: 4,
    question: '日本で最も多くの他の都道府県と隣接している県はどこでしょう？（隣接数：8県）',
    options: ['岐阜県', '長野県', '埼玉県', '京都府'],
    correctIndex: 1,
    explanation: '長野県は群馬県、新潟県、富山県、岐阜県、山梨県、静岡県、愛知県の合計8県に囲まれており、日本最多の隣接数を誇ります。第2位は岐阜県の7県（富山・石川・福井・長野・愛知・三重・滋賀）です。',
    prefecture: '長野県'
  },
  {
    id: 5,
    question: '日本には海に面していない「内陸県」が8県ありますが、地方区分で内陸県が存在しない地方はどこでしょう？',
    options: ['関東地方', '中部地方', '東北地方', '近畿地方'],
    correctIndex: 2,
    explanation: '内陸県は栃木県・群馬県・埼玉県（関東3県）、山梨県・長野県・岐阜県（中部3県）、滋賀県・奈良県（近畿2県）の計8県です。東北地方の6県はすべて太平洋または日本海（あるいは両方）に面しています。',
    prefecture: '東北地方'
  }
];

import { useState } from 'react';
import { quizQuestions } from './quizData';
import { UserAnswer } from './types';
import { MapPin, CheckCircle2, XCircle, ArrowRight, RotateCcw, BookOpen, Award } from 'lucide-react';
import './index.css';

const OPTION_LABELS = ['A', 'B', 'C', 'D'];

export default function App() {
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [userAnswers, setUserAnswers] = useState<UserAnswer[]>([]);
  const [isCompleted, setIsCompleted] = useState<boolean>(false);

  const totalQuestions = quizQuestions.length;
  const currentQuestion = quizQuestions[currentIndex];
  const isAnswered = selectedOption !== null;

  const handleSelectOption = (index: number) => {
    if (isAnswered) return;

    const isCorrect = index === currentQuestion.correctIndex;
    setSelectedOption(index);

    const newAnswer: UserAnswer = {
      questionId: currentQuestion.id,
      selectedIndex: index,
      isCorrect,
    };

    setUserAnswers((prev) => [...prev, newAnswer]);
  };

  const handleNext = () => {
    if (currentIndex < totalQuestions - 1) {
      setCurrentIndex((prev) => prev + 1);
      setSelectedOption(null);
    } else {
      setIsCompleted(true);
    }
  };

  const handleRestart = () => {
    setCurrentIndex(0);
    setSelectedOption(null);
    setUserAnswers([]);
    setIsCompleted(false);
  };

  const correctCount = userAnswers.filter((ans) => ans.isCorrect).length;

  const getResultComment = (score: number) => {
    if (score === totalQuestions) {
      return '全問正解！完璧な日本の地理マスターです！日本の隅々まで知り尽くしていますね。';
    } else if (score >= 3) {
      return '素晴らしい成績！日本の地理に関する確かな知識をお持ちです。';
    } else {
      return 'お疲れ様でした！解説を読んで新しい日本の魅力を発見してみてください。';
    }
  };

  return (
    <div className="quiz-app">
      <header className="quiz-header">
        <h1 className="quiz-title">
          <span>🗾</span> 日本の地理クイズ
        </h1>
        <p className="quiz-subtitle">
          都道府県の広さや川、湖、境界に関する厳選4択クイズ
        </p>
      </header>

      {!isCompleted ? (
        <>
          <div className="progress-wrapper">
            <div className="progress-info">
              <span>進捗状況</span>
              <span>
                第 {currentIndex + 1} 問 / 全 {totalQuestions} 問
              </span>
            </div>
            <div className="progress-bar-bg">
              <div
                className="progress-bar-fill"
                style={{
                  width: `${((currentIndex + (isAnswered ? 1 : 0)) / totalQuestions) * 100}%`,
                }}
              />
            </div>
          </div>

          <div className="quiz-card">
            <div className="question-meta">
              <span className="badge-prefecture">
                <MapPin size={14} />
                {currentQuestion.prefecture}
              </span>
            </div>

            <h2 className="question-text">
              Q{currentIndex + 1}. {currentQuestion.question}
            </h2>

            <div className="options-grid">
              {currentQuestion.options.map((option, idx) => {
                let btnStateClass = 'option-btn-default';

                if (isAnswered) {
                  if (idx === currentQuestion.correctIndex) {
                    btnStateClass = 'option-btn-correct';
                  } else if (idx === selectedOption) {
                    btnStateClass = 'option-btn-incorrect';
                  }
                }

                return (
                  <button
                    key={idx}
                    type="button"
                    className={`option-btn ${btnStateClass}`}
                    onClick={() => handleSelectOption(idx)}
                    disabled={isAnswered}
                  >
                    <span className="option-label">{OPTION_LABELS[idx]}</span>
                    <span className="option-text">{option}</span>
                  </button>
                );
              })}
            </div>

            {isAnswered && (
              <div className="explanation-card">
                <div className="explanation-header">
                  <BookOpen size={18} color="#1d3557" />
                  <span className="explanation-title">
                    {selectedOption === currentQuestion.correctIndex ? '正解！' : '不正解…'}
                    【解説・豆知識】
                  </span>
                </div>
                <p className="explanation-body">{currentQuestion.explanation}</p>
              </div>
            )}

            {isAnswered && (
              <div className="action-wrapper">
                <button type="button" className="next-btn" onClick={handleNext}>
                  <span>{currentIndex < totalQuestions - 1 ? '次の問題へ' : '結果を見る'}</span>
                  <ArrowRight size={18} />
                </button>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="result-card">
          <div className="result-badge">
            <Award size={14} style={{ display: 'inline', marginRight: '4px', verticalAlign: '-2px' }} />
            クイズ終了
          </div>

          <div className="result-score-box">
            <span className="result-score-num">{correctCount}</span>
            <span className="result-score-denom">/ {totalQuestions} 問正解</span>
          </div>

          <p className="result-comment">{getResultComment(correctCount)}</p>

          <div className="result-summary-list">
            {quizQuestions.map((question, idx) => {
              const answer = userAnswers.find((ans) => ans.questionId === question.id);
              const isCorrect = answer?.isCorrect ?? false;

              return (
                <div
                  key={question.id}
                  className={`summary-item ${isCorrect ? 'summary-item-correct' : 'summary-item-incorrect'}`}
                >
                  <div className="summary-q-title">
                    <span>
                      Q{idx + 1}. {question.question}
                    </span>
                    {isCorrect ? (
                      <CheckCircle2 size={20} color="#2b7a4b" style={{ flexShrink: 0 }} />
                    ) : (
                      <XCircle size={20} color="#c53030" style={{ flexShrink: 0 }} />
                    )}
                  </div>
                  <div className="summary-detail">
                    正解: <strong>{question.options[question.correctIndex]}</strong>
                    {answer && !isCorrect && (
                      <span>（あなたの回答: {question.options[answer.selectedIndex]}）</span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>

          <button type="button" className="restart-btn" onClick={handleRestart}>
            <RotateCcw size={18} />
            <span>もう一度挑戦する</span>
          </button>
        </div>
      )}
    </div>
  );
}
